import{z as A,x as s,o as e,c as l,q as n,j as t,D as E,d as r,s as o,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"前瞻指引之谜","description":"","frontmatter":{"title":"前瞻指引之谜","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fg-puzzle.md","filePath":"econ/fg-puzzle.md","lastUpdated":1791063341000}'),p={name:"econ/fg-puzzle.md"};function d(C,a,D,h,c,m){const B=s("Mermaid");return e(),l("div",null,[a[2]||(a[2]=n('<h1 id="前瞻指引之谜" tabindex="-1">前瞻指引之谜 <a class="header-anchor" href="#前瞻指引之谜" aria-label="Permalink to &quot;前瞻指引之谜&quot;">​</a></h1><div class="epigraph"><p>标准新凯恩斯里，对很远未来的利率许诺会通过欧拉几乎不贴现地冲进今天的缺口；数据里没有这么大的魔力。</p><footer>—— Del Negro, Giannoni and Patterson 对前瞻指引之谜的定量对照；McKay, Nakamura and Steinsson, AER 2016</footer></div><p><a href="/econ/zlb-unconventional">上一课</a>把下限上的工具写成路径承诺：更低更久的 \\(i\\) 进入欧拉。QE 与话的分工是后课。本课的缺口是定量：同一套动态 IS，把未来第 \\(T\\) 期的 \\(i\\) 下调，当前 \\(\\tilde{y}\\)、\\(\\pi\\) 的反应随 \\(T\\) 衰减得<strong>太慢</strong>，甚至可以随 \\(T\\) 变大——前瞻指引之谜。Del Negro、Giannoni 与 Patterson 把标准 NK 与 DSGE 的放大对照数据；McKay–Nakamura–Steinsson 用不完全市场压贴现。本课不发明某一次记者会的基点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>动态 IS 向前迭代，\\(\\tilde{y}_t\\) 含一整串未来实际利率。若无折现摩擦，第 \\(T\\) 期的 \\(r\\) 与第 1 期几乎同等进入今天的消费。NKPC 再把未来缺口贴现进当前 \\(\\pi\\)，于是「十年后才降息」也可以大幅移动今天。这与直觉和估计的政策乘数不符。缺口不是再解释下限为何存在，而是：欧拉加完全市场把远期指引变得过强。谜是模型相对数据的夸大，不是「指引完全无效」。</p><p><span class="marginnote">日历指引（「到某年某月」）最容易触发谜：承诺的是远日期，不是状态。状态依存指引与价格水平目标在理论上仍强，但谜迫使你检查贴现。</span></p><p><span class="marginnote">常见误区：把谜读成「前瞻指引没用」。谜说的是教科书模型把效应放大得离谱，方向上承诺依然有效。修补之后指引仍能移动预期，只是弹性随承诺日期衰减——不再出现「十年后才降息等于明天就降息」的荒谬杠杆，而不是「说话无效」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在线性 NK 里对未来某一期的政策利率做预期冲击，画出当前缺口对 \\(T\\) 的反应：标准校准下衰减过慢。Del Negro–Giannoni–Patterson 用估计 DSGE 说明远期冲击的效应过大，并提出对预期或对远期利率反应的折扣作为修补。McKay、Nakamura 与 Steinsson（2016）：不完全市场与借贷约束使收入风险进入贴现，远期利率对当前消费的权重下降，谜减弱。习惯、有限信息、有限计划区间是平行修补。</p>',9)),(e(),t(i,null,{default:E(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ELB%5B%22%E4%B8%8B%E9%99%90%EF%BC%9A%E8%AF%9D%E6%94%B9%E6%9C%AA%E6%9D%A5%20i%22%5D%20--%3E%20EU%5B%22%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%E6%AC%A7%E6%8B%89%22%5D%0A%20%20EU%20--%3E%20BIG%5B%22%E8%BF%9C%E6%9C%9F%E5%86%B2%E5%87%BB%20%E2%89%88%20%E5%BD%93%E6%9C%9F%E5%86%B2%E5%87%BB%22%5D%0A%20%20BIG%20--%3E%20PUZ%5B%22%E7%9B%B8%E5%AF%B9%E6%95%B0%E6%8D%AE%E8%BF%87%E5%A4%A7%22%5D%0A%20%20IM%5B%22%E4%B8%8D%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%20%2F%20%E6%8A%98%E6%89%A3%22%5D%20--%3E%20DAMP%5B%22%E8%BF%9C%E6%9C%9F%E6%9D%83%E9%87%8D%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>话与表下一课再拆。本课只要求：用标准三方程宣传「远期承诺效力无限」时，必须声明谜。CIP 与期限溢价的市场层证据在<a href="/quant/irp">量化栏</a>与期限结构课，不在本课估指引的基点。</p><h3 id="不是否定承诺" tabindex="-1">不是否定承诺 <a class="header-anchor" href="#不是否定承诺" aria-label="Permalink to &quot;不是否定承诺&quot;">​</a></h3><p>Eggertsson–Woodford 的最优仍是路径与价格水平。谜说的是<strong>定量放大</strong>，不是符号。修补之后，指引仍可以动 \\(\\mathbb{E}r\\)，只是弹性不再随 \\(T\\) 保持荒谬。卢卡斯批判：若公众不信远期许诺，效应本来就小——那是可信度，与不完全市场是两句。</p><h3 id="谜在正利率区同样成立" tabindex="-1">谜在正利率区同样成立 <a class="header-anchor" href="#谜在正利率区同样成立" aria-label="Permalink to &quot;谜在正利率区同样成立&quot;">​</a></h3><p>任何「预先宣布很久以后才动 \\(i\\)」都会被标准欧拉放大。下限只是使这种宣布变成常用工具，不是谜的定义域。</p><p>因此修补必须改贴现结构，不能指望「离开下限后谜自动消失」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完全保险下，家庭只在乎整条实际利率路径的积分，日期不重要。有未保险冲击时，今天的紧约束家庭对「十年后更低的 \\(i\\)」几乎无反应，当前 MPC 主导，远期欧拉链条断开。于是同样的下限承诺，当前乘数变小、更合理。混合 NKPC 的惯性会再改通胀侧的放大，但不单独解开消费欧拉的谜。</p>',8)),(e(),t(i,null,{default:E(()=>[o(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROMISE%5B%22%E6%89%BF%E8%AF%BA%E5%8D%81%E5%B9%B4%E5%90%8E%E9%99%8D%E6%81%AF%22%5D%20--%3E%20CM%5B%22%E4%B8%96%E7%95%8C%E4%B8%80%EF%BC%9A%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%22%5D%0A%20%20CM%20--%3E%20SMOOTH%5B%22%E6%B6%88%E8%B4%B9%E5%8F%AF%E5%9C%A8%E4%BB%BB%E6%84%8F%E4%B8%A4%E6%9C%9F%E4%B9%8B%E9%97%B4%E6%90%AC%E9%92%B1%22%5D%0A%20%20SMOOTH%20--%3E%20BIG%5B%22%E4%BB%8A%E5%A4%A9%E6%B6%88%E8%B4%B9%E5%A4%A7%E5%8A%A8%EF%BC%9A%E8%B0%9C%E5%87%BA%E7%8E%B0%22%5D%0A%20%20PROMISE%20--%3E%20IM%5B%22%E4%B8%96%E7%95%8C%E4%BA%8C%EF%BC%9A%E4%B8%8D%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%22%5D%0A%20%20IM%20--%3E%20CONSTR%5B%22%E8%AE%B8%E5%A4%9A%E5%AE%B6%E5%BA%AD%E6%AD%A3%E8%A2%AB%E5%80%9F%E8%B4%B7%E7%BA%A6%E6%9D%9F%E5%8D%A1%E4%BD%8F%22%5D%0A%20%20CONSTR%20--%3E%20MPC%5B%22%E4%BB%96%E4%BB%AC%E5%8F%AA%E8%83%BD%E8%8A%B1%E5%BD%93%E6%9C%9F%E6%94%B6%E5%85%A5%EF%BC%9AMPC%20%E9%AB%98%22%5D%0A%20%20MPC%20--%3E%20SMALL%5B%22%E8%BF%9C%E6%9C%9F%E5%88%A9%E7%8E%87%E4%BC%A0%E4%B8%8D%E8%BF%9B%E5%BD%93%E5%89%8D%E6%B6%88%E8%B4%B9%EF%BC%9A%E8%B0%9C%E5%87%8F%E5%BC%B1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">数字实例：标准三方程模型里，把十年后的利率临时下调 1 个百分点，今天的产出缺口响应可以与「明天就降息 1 个百分点」几乎一样大——远期权重几乎不衰减。而事件研究估计的指引效应通常随承诺日期拉远明显缩水。模型脉冲与数据脉冲对不上号，这个反差就是谜本身。</span></p><p>可信度折扣与市场不完全可以一起出现：不信则远期 \\(\\mathbb{E}i\\) 不动；信但不完全市场，则 \\(\\mathbb{E}i\\) 动了也传不进当前 \\(c\\)。政策评估必须声明是哪一层。</p><p><span class="marginnote">直觉类比：完全市场的家庭像有无限额度的信用卡，钱可以在任意两期之间搬动，「十年后的低利率」今天就能兑换成消费；月光族则刷不动未来——下个月工资不变，今晚的饭不会因此多吃一口。经济里月光族（受约束家庭）越多，远期指引的杠杆越短。</span></p><p>价格水平目标把远期许诺改成对价格路径的积分约束，理论上仍强，但若公众用有限计划或不完全市场贴现，当前效应同样被压。谜因此不只打击日历日期，也打击「任何很远的名义路径」。修补之后仍应说话，只是不要用教科书欧拉当效应表。</p><p><span class="marginnote">谜在正利率区同样存在：任何「预先宣布很久以后的 \\(i\\)」都会被标准欧拉放大。下限只是使这种宣布变成常规工具。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计某次 FOMC 声明的产出弹性，不把谜写成「因此不要说话」。QE 渠道（久期、信号）下一课才与话并列。量化栏没有宏观欧拉折扣。也不要把谜当成财政乘数的替代。</p><p>有限信息与粘性信息（Mankiw–Reis 一类）同样衰减远期冲击：没注意到的远期许诺进不了当前欧拉。这与不完全市场并列，不要焊成一个参数。经验上指引仍能动利率路径与预期，只是远小于标准 NK 的脉冲。政策含义是把话写短、写状态依存，并配表当可见抵押——下一课。</p><p>后课默认：下限上路径承诺在符号上仍成立，定量要用能衰减远期权重的装置，不能拿教科书欧拉当乘数表。下一课：把话与资产负债表拆开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>下限课给出指引的符号；本课指出标准 NK 把远期冲击放得过大。</li><li>完全市场欧拉几乎不贴现远期 \\(r\\)。</li><li>不完全市场、折扣预期、有限计划是修补。</li><li>谜是定量，不是否定承诺的方向。</li><li>出处：Del Negro, Giannoni and Patterson 的对照；McKay, Nakamura and Steinsson, <em>AER</em> 2016。</li></ul>',11))])}const F=A(p,[["render",d]]);export{u as __pageData,F as default};
